describe("① 一次受理小说第一步：拿到卡号与尝试号，能按卡号查回该卡", () => {
	it("受理写作部门第一步，返回真实卡号与卡路径，卡内容与请求一致", async () => {
		const fixture = makeFixture("accept-one");
		const dispatch = makeDispatchHook();

		const report = await acceptIntake(
			fixture.cardsDir,
			[
				request({
					idempotencyKey: "小说-第一章-初稿",
