					JSON.parse(
						readFileSync(integrationResultPath(sourceExecution.key.cardsDir, `req-check-stop-${name}`), "utf8"),
					) as IntegrationRecord,
				);
			} finally {
				controller.abort();
				await operation;
				// 仅结束本用例刚创建且仍存在的检查进程；无派生进程，退出后不再碰 PID。
				if (existsSync(ready)) {
					const pid = Number(readFileSync(ready, "utf8"));
					try {
						process.kill(pid);
					} catch (error) {
						if ((error as NodeJS.ErrnoException).code !== "ESRCH") throw error;
					}
				}
			}
		}
	}, 60000);
});

