		expect(outcomes.map((outcome) => outcome.pid).every((pid) => processAlive(pid) === false)).toBe(true);
		const events = existsSync(log)
			? readFileSync(log, "utf8")
					.split("\n")
					.filter(Boolean)
					.map((line) => {
						const [event, time, id, pid] = line.split(" ");
