			},
		);

		const operation = runCardProcess("fake-native-overflow", [], process.cwd(), 60000);
		await expect(operation).rejects.toMatchObject({
			name: "CardProcessStopUnconfirmedError",
			message: expect.stringContaining("原生命令输出上限先触发"),
