			name: "CardProcessStopUnconfirmedError",
			message: expect.stringContaining("命令自行退出"),
		});
		expect(killTreeMock).toHaveBeenCalledWith(43002, 0, expect.any(Number));
	});
});

describe("verifyCard：跑命令条目遇停止链失败的降级", () => {
