		const op = runCardProcess(process.execPath, hangArgs(), tempDir(), 100);
		await expect(op).rejects.toBeInstanceOf(CardProcessStopUnconfirmedError);
		await expect(op).rejects.toThrow("PowerShell 树杀超时失败");
		await op.catch(() => {});
	});

