				if (existsSync(ready)) {
					const pid = Number(readFileSync(ready, "utf8"));
					try {
						process.kill(pid);
					} catch (error) {
						if ((error as NodeJS.ErrnoException).code !== "ESRCH") throw error;
					}
				}
			}
		}
	}, 60000);
});

